// Build cart line inputs using merchandise GIDs — always from variant external ids as numeric strings
const cartLines = selected_variant_external_ids.map((vid: ShopifyVariantExternalId) => ({
  merchandiseId: variantMerchandiseGid(vid),
  quantity: 1,
}));

new_string:
// Build cart line inputs using merchandise GIDs sourced directly from the inbound
// selected_variant_gids field (which the widget populated from live_variant_gid on each
// bundle component — never constructed locally from numeric ids).
const cartLines = (selected_variant_gids as StorefrontVariantGid[]).map((gid) => ({
  merchandiseId: gid,
  quantity: 1,
}));
